-- Reviewed SAS New Brunswick Philosophy B.A. (program code 730).

VALUES ('sasnb-philosophy-major','Philosophy','sasnb','philosophy-major','major','Current official page','730','B.A.','sasnb-philosophy-730','https://philosophy.rutgers.edu/major','reviewed',strftime('%s','now')*1000,1)
ON CONFLICT(id) DO UPDATE SET name=excluded.name,school_slug=excluded.school_slug,program_slug=excluded.program_slug,type=excluded.type,catalog_year=excluded.catalog_year,academic_program_code=excluded.academic_program_code,degree_type=excluded.degree_type,program_family_id=excluded.program_family_id,source_url=excluded.source_url,review_status=excluded.review_status,last_scraped_at=excluded.last_scraped_at,requirement_evidence_required=excluded.requirement_evidence_required;

ON CONFLICT(program_id,source_url) DO UPDATE SET source_title=excluded.source_title,source_catalog_year=excluded.source_catalog_year,source_scope=excluded.source_scope,accessed_at=excluded.accessed_at,note=excluded.note;

DELETE FROM program_requirement_evidence WHERE program_id='sasnb-philosophy-major';
DELETE FROM requirement_course_selectors WHERE group_id IN (SELECT id FROM requirement_groups WHERE program_id='sasnb-philosophy-major');
DELETE FROM requirement_courses WHERE group_id IN (SELECT id FROM requirement_groups WHERE program_id='sasnb-philosophy-major');
DELETE FROM requirement_groups WHERE program_id='sasnb-philosophy-major';
DELETE FROM program_eligibility_rules WHERE program_id='sasnb-philosophy-major';



-- The published major list identifies each named course as three credits.
UPDATE requirement_courses SET source_credits='3'
WHERE group_id IN (SELECT id FROM requirement_groups WHERE program_id='sasnb-philosophy-major');

ON CONFLICT(group_id,selector_key) DO UPDATE SET selector_json=excluded.selector_json,source_url=excluded.source_url,source_label=excluded.source_label,review_status=excluded.review_status,reviewed_at=excluded.reviewed_at;

SELECT 'group:'||id,'sasnb-philosophy-major','group',id,NULL,'https://philosophy.rutgers.edu/major','Philosophy Major',NULL,strftime('%s','now')*1000,'Current official Philosophy major requirement.','reviewed'
FROM requirement_groups WHERE program_id='sasnb-philosophy-major';
SELECT 'course:'||group_id||':'||course_code,'sasnb-philosophy-major','course',group_id,course_code,'https://philosophy.rutgers.edu/major','Philosophy Major',NULL,strftime('%s','now')*1000,'Current official Philosophy major requirement.','reviewed'
FROM requirement_courses WHERE group_id IN (SELECT id FROM requirement_groups WHERE program_id='sasnb-philosophy-major');

ON CONFLICT(rule_key) DO UPDATE SET program_id=excluded.program_id,condition_type=excluded.condition_type,condition_value_json=excluded.condition_value_json,decision=excluded.decision,note=excluded.note,source_url=excluded.source_url,review_status=excluded.review_status,verified_at=excluded.verified_at;
